from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        if key not in cache:
            return True
        _, wt = cache[key]
        return t >= wt + ttl

    for op in ops:
        kind = op[0]
        t = op[1]
        if kind == 'put':
            key, value = op[2], op[3]
            if key in cache:
                if is_expired(key, t):
                    del cache[key]
                else:
                    del cache[key]
            if key not in cache and len(cache) >= capacity:
                # evict expired entries first if any at front, else LRU
                # need to evict least recently used entry
                # remove expired entries lazily but eviction rule: evict LRU
                # find first entry (LRU) 
                evict_key = next(iter(cache))
                del cache[evict_key]
            cache[key] = (value, t)
            cache.move_to_end(key)
        else:
            key = op[2]
            if key in cache and not is_expired(key, t):
                value, wt = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                if key in cache:
                    del cache[key]
                results.append(-1)

    return results

